    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'NET30',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'NET30');
  assert.equal(result.value.dueDate, '2025-11-14');
});

test('createInvoice accepts EOM terms', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
    terms: 'EOM',
  });

  assert.equal(result.ok, true);
  assert.equal(result.value.terms, 'EOM');
  assert.equal(result.value.dueDate, '2025-10-31');
});

test('createInvoice EOM works for different months', () => {
  // February in non-leap year
  let result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2025-02-28');

  // February in leap year
  result = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-10',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2024-02-29');

  // December (year boundary)
  result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-12-20',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'EOM',
  });
  assert.equal(result.value.dueDate, '2025-12-31');
});

test('createInvoice rejects invalid terms', () => {
  assert.deepEqual(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'NET60',
