  );

  assert.deepEqual(
    createInvoice({
      customerId: 'C-002',
      issueDate: '2025-10-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
      terms: 'INVALID',
    }),
    { ok: false, error: 'TERMS_INVALID' }
  );
});

