  assert.equal(calculateDueDate('2025-10-15', 'NET14'), '2025-10-29');
  assert.equal(calculateDueDate('2025-01-01', 'NET14'), '2025-01-15');
});

test('calculateDueDate with NET30', () => {
  assert.equal(calculateDueDate('2025-10-15', 'NET30'), '2025-11-14');
  assert.equal(calculateDueDate('2025-01-01', 'NET30'), '2025-01-31');
});

test('calculateDueDate with EOM', () => {
  assert.equal(calculateDueDate('2025-10-15', 'EOM'), '2025-10-31');
  assert.equal(calculateDueDate('2025-10-01', 'EOM'), '2025-10-31');
  assert.equal(calculateDueDate('2025-10-31', 'EOM'), '2025-10-31');
