test('calculateDueDate EOM handles different month lengths', () => {
  assert.equal(calculateDueDate('2025-02-10', 'EOM'), '2025-02-28'); // Feb non-leap
  assert.equal(calculateDueDate('2024-02-10', 'EOM'), '2024-02-29'); // Feb leap
  assert.equal(calculateDueDate('2025-04-10', 'EOM'), '2025-04-30'); // April has 30 days
  assert.equal(calculateDueDate('2025-05-10', 'EOM'), '2025-05-31'); // May has 31 days
});

test('calculateDueDate EOM crosses year boundary', () => {
  assert.equal(calculateDueDate('2025-12-10', 'EOM'), '2025-12-31');
  assert.equal(calculateDueDate('2025-12-31', 'EOM'), '2025-12-31');
});

test('calculateDueDate NET14 crosses year boundary', () => {
