});

test('calculateDueDate NET30 crosses year boundary', () => {
  assert.equal(calculateDueDate('2025-12-05', 'NET30'), '2026-01-04');
});

test('calculateDueDate with invalid terms returns null', () => {
  assert.equal(calculateDueDate('2025-10-15', 'NET60'), null);
  assert.equal(calculateDueDate('2025-10-15', 'INVALID'), null);
  assert.equal(calculateDueDate('2025-10-15', ''), null);
});

